import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64

.visible .entry attention_kernel(
    .param .u64 pQ,
    .param .u64 pK,
    .param .u64 pV,
    .param .u64 pO
)
{
    .shared .align 2 .b16 sh_q[1024];
    .shared .align 4 .f32 sh_score[256];
    .shared .align 4 .f32 sh_red[256];
    .shared .align 4 .f32 sh_max[1];
    .shared .align 4 .f32 sh_denom[1];

    .reg .pred %p_t256, %p_lane0, %p_j, %p_n, %p_off, %p_t0;
    .reg .b16 %rh_q, %rh_k, %rh_v, %rh_o;
    .reg .b32 %r_b, %r_h, %r_i, %r_tid, %r_lane, %r_warp;
    .reg .b32 %r_bh, %r_head, %r_qrow, %r_elem, %r_byte;
    .reg .b32 %r_sq, %r_ss, %r_sr, %r_smax, %r_sden;
    .reg .b32 %r_qaddr, %r_score_addr, %r_red_addr, %r_red_addr2;
    .reg .b32 %r_j0, %r_j, %r_t, %r_n, %r_off, %r_offb;
    .reg .b32 %r_bits, %r_sh, %r_tmp32;
    .reg .b64 %rd_Q, %rd_K, %rd_V, %rd_O;
    .reg .b64 %rd_off, %rd_q, %rd_o, %rd_klane, %rd_kt, %rd_v;
    .reg .f32 %f_q, %f_k, %f_v, %f_part, %f_tmp, %f_scale;
    .reg .f32 %f_score, %f_a, %f_b, %f_m, %f_max, %f_e, %f_den, %f_p, %f_acc;
    .reg .f32 %f_log2e, %f_neginf, %f_zero;

    mov.u32 %r_b, %ctaid.z;
    mov.u32 %r_h, %ctaid.y;
    mov.u32 %r_i, %ctaid.x;
    mov.u32 %r_tid, %tid.x;
    and.b32 %r_lane, %r_tid, 31;
    shr.u32 %r_warp, %r_tid, 5;

    ld.param.u64 %rd_Q, [pQ];
    ld.param.u64 %rd_K, [pK];
    ld.param.u64 %rd_V, [pV];
    ld.param.u64 %rd_O, [pO];

    mov.f32 %f_scale, 0f3D000000;
    mov.f32 %f_log2e, 0f3FB8AA3B;
    mov.f32 %f_neginf, 0fFF800000;
    mov.f32 %f_zero, 0f00000000;

    mad.lo.u32 %r_bh, %r_b, 32, %r_h;
    mul.lo.u32 %r_head, %r_bh, 262144;
    mad.lo.u32 %r_qrow, %r_i, 1024, %r_head;
    add.u32 %r_elem, %r_qrow, %r_tid;
    shl.b32 %r_byte, %r_elem, 1;
    cvt.u64.u32 %rd_off, %r_byte;

    add.u64 %rd_q, %rd_Q, %rd_off;
    ld.global.u16 %rh_q, [%rd_q];
    mov.u32 %r_sq, sh_q;
    shl.b32 %r_tmp32, %r_tid, 1;
    add.u32 %r_qaddr, %r_sq, %r_tmp32;
    st.shared.u16 [%r_qaddr], %rh_q;

    add.u64 %rd_o, %rd_O, %rd_off;
    add.u32 %r_elem, %r_head, %r_tid;
    shl.b32 %r_byte, %r_elem, 1;
    cvt.u64.u32 %rd_off, %r_byte;
    add.u64 %rd_v, %rd_V, %rd_off;
    bar.sync 0;

    shl.b32 %r_j0, %r_warp, 3;
    mul.lo.u32 %r_tmp32, %r_j0, 1024;
    add.u32 %r_elem, %r_head, %r_tmp32;
    shl.b32 %r_byte, %r_elem, 1;
    shl.b32 %r_tmp32, %r_lane, 1;
    add.u32 %r_byte, %r_byte, %r_tmp32;
    cvt.u64.u32 %rd_off, %r_byte;
    add.u64 %rd_klane, %rd_K, %rd_off;

    mov.u32 %r_sq, sh_q;
    shl.b32 %r_tmp32, %r_lane, 1;
    add.u32 %r_qaddr, %r_sq, %r_tmp32;

    mov.u32 %r_ss, sh_score;
    mov.u32 %r_j, %r_j0;
    mov.u32 %r_t, 0;
    shl.b32 %r_tmp32, %r_j0, 2;
    add.u32 %r_score_addr, %r_ss, %r_tmp32;

L_KEY:
    mov.u64 %rd_kt, %rd_klane;
    mov.u32 %r_qaddr, %r_sq;
    shl.b32 %r_tmp32, %r_lane, 1;
    add.u32 %r_qaddr, %r_qaddr, %r_tmp32;
    mov.u32 %r_n, 0;
    mov.f32 %f_part, %f_zero;

L_N:
    ld.global.u16 %rh_k, [%rd_kt];
    ld.shared.u16 %rh_q, [%r_qaddr];
    cvt.f32.f16 %f_k, %rh_k;
    cvt.f32.f16 %f_q, %rh_q;
    fma.rn.f32 %f_part, %f_q, %f_k, %f_part;
    add.u64 %rd_kt, %rd_kt, 64;
    add.u32 %r_qaddr, %r_qaddr, 64;
    add.u32 %r_n, %r_n, 1;
    setp.lt.u32 %p_n, %r_n, 32;
    @%p_n bra L_N;

    mov.b32 %r_bits, %f_part;
    shfl.sync.down.b32 %r_sh, %r_bits, 16, 0x1f, 0xffffffff;
    mov.b32 %f_tmp, %r_sh;
    add.f32 %f_part, %f_part, %f_tmp;
    mov.b32 %r_bits, %f_part;
    shfl.sync.down.b32 %r_sh, %r_bits, 8, 0x1f, 0xffffffff;
    mov.b32 %f_tmp, %r_sh;
    add.f32 %f_part, %f_part, %f_tmp;
    mov.b32 %r_bits, %f_part;
    shfl.sync.down.b32 %r_sh, %r_bits, 4, 0x1f, 0xffffffff;
    mov.b32 %f_tmp, %r_sh;
    add.f32 %f_part, %f_part, %f_tmp;
    mov.b32 %r_bits, %f_part;
    shfl.sync.down.b32 %r_sh, %r_bits, 2, 0x1f, 0xffffffff;
    mov.b32 %f_tmp, %r_sh;
    add.f32 %f_part, %f_part, %f_tmp;
    mov.b32 %r_bits, %f_part;
    shfl.sync.down.b32 %r_sh, %r_bits, 1, 0x1f, 0xffffffff;
    mov.b32 %f_tmp, %r_sh;
    add.f32 %f_part, %f_part, %f_tmp;

    setp.eq.u32 %p_lane0, %r_lane, 0;
    mul.f32 %f_score, %f_part, %f_scale;
    @%p_lane0 st.shared.f32 [%r_score_addr], %f_score;

    add.u64 %rd_klane, %rd_klane, 2048;
    add.u32 %r_score_addr, %r_score_addr, 4;
    add.u32 %r_j, %r_j, 1;
    add.u32 %r_t, %r_t, 1;
    setp.lt.u32 %p_j, %r_t, 8;
    @%p_j bra L_KEY;

    bar.sync 0;

    setp.lt.u32 %p_t256, %r_tid, 256;
    mov.u32 %r_ss, sh_score;
    shl.b32 %r_tmp32, %r_tid, 2;
    add.u32 %r_score_addr, %r_ss, %r_tmp32;
    mov.u32 %r_sr, sh_red;
    add.u32 %r_red_addr, %r_sr, %r_tmp32;

    mov.f32 %f_a, %f_neginf;
    @%p_t256 ld.shared.f32 %f_a, [%r_score_addr];
    @%p_t256 st.shared.f32 [%r_red_addr], %f_a;
    bar.sync 0;

    mov.u32 %r_off, 128;
L_MAX_RED:
    setp.lt.u32 %p_off, %r_tid, %r_off;
    @!%p_off bra L_MAX_SKIP;
    shl.b32 %r_offb, %r_off, 2;
    add.u32 %r_red_addr2, %r_red_addr, %r_offb;
    ld.shared.f32 %f_a, [%r_red_addr];
    ld.shared.f32 %f_b, [%r_red_addr2];
    max.f32 %f_m, %f_a, %f_b;
    st.shared.f32 [%r_red_addr], %f_m;
L_MAX_SKIP:
    bar.sync 0;
    shr.u32 %r_off, %r_off, 1;
    setp.gt.u32 %p_off, %r_off, 0;
    @%p_off bra L_MAX_RED;

    mov.u32 %r_smax, sh_max;
    setp.eq.u32 %p_t0, %r_tid, 0;
    @%p_t0 ld.shared.f32 %f_max, [%r_sr];
    @%p_t0 st.shared.f32 [%r_smax], %f_max;
    bar.sync 0;

    ld.shared.f32 %f_max, [%r_smax];
    @%p_t256 ld.shared.f32 %f_score, [%r_score_addr];
    sub.f32 %f_tmp, %f_score, %f_max;
    mul.f32 %f_tmp, %f_tmp, %f_log2e;
    ex2.approx.f32 %f_e, %f_tmp;
    @%p_t256 st.shared.f32 [%r_score_addr], %f_e;
    @%p_t256 st.shared.f32 [%r_red_addr], %f_e;
    bar.sync 0;

    mov.u32 %r_off, 128;
L_SUM_RED:
    setp.lt.u32 %p_off, %r_tid, %r_off;
    @!%p_off bra L_SUM_SKIP;
    shl.b32 %r_offb, %r_off, 2;
    add.u32 %r_red_addr2, %r_red_addr, %r_offb;
    ld.shared.f32 %f_a, [%r_red_addr];
    ld.shared.f32 %f_b, [%r_red_addr2];
    add.f32 %f_a, %f_a, %f_b;
    st.shared.f32 [%r_red_addr], %f_a;
L_SUM_SKIP:
    bar.sync 0;
    shr.u32 %r_off, %r_off, 1;
    setp.gt.u32 %p_off, %r_off, 0;
    @%p_off bra L_SUM_RED;

    mov.u32 %r_sden, sh_denom;
    @%p_t0 ld.shared.f32 %f_den, [%r_sr];
    @%p_t0 st.shared.f32 [%r_sden], %f_den;
    bar.sync 0;

    ld.shared.f32 %f_den, [%r_sden];
    @%p_t256 ld.shared.f32 %f_e, [%r_score_addr];
    div.rn.f32 %f_p, %f_e, %f_den;
    @%p_t256 st.shared.f32 [%r_score_addr], %f_p;
    bar.sync 0;

    mov.f32 %f_acc, %f_zero;
    mov.u32 %r_j, 0;
    mov.u32 %r_ss, sh_score;
    mov.u32 %r_score_addr, %r_ss;

L_OUT:
    ld.global.u16 %rh_v, [%rd_v];
    cvt.f32.f16 %f_v, %rh_v;
    ld.shared.f32 %f_p, [%r_score_addr];
    fma.rn.f32 %f_acc, %f_p, %f_v, %f_acc;
    add.u64 %rd_v, %rd_v, 2048;
    add.u32 %r_score_addr, %r_score_addr, 4;
    add.u32 %r_j, %r_j, 1;
    setp.lt.u32 %p_j, %r_j, 256;
    @%p_j bra L_OUT;

    cvt.rn.f16.f32 %rh_o, %f_acc;
    st.global.u16 [%rd_o], %rh_o;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("attention_kernel")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, Q: torch.Tensor, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        out = torch.empty(Q.shape, dtype=Q.dtype, device=Q.device)
        module = _get_ptx_module()
        module.launch(
            "attention_kernel",
            grid=(Q.shape[2], Q.shape[1], Q.shape[0]),
            block=(1024, 1, 1),
            arguments=[Q, K, V, out],
            shared_memory=0,
            stream=torch.cuda.current_stream(Q.device),
        )
        return out

